#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public struct FfiConverterTypePlatformAppEngine: FfiConverter {
    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = PlatformAppEngine

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> PlatformAppEngine {
        return PlatformAppEngine(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: PlatformAppEngine) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PlatformAppEngine {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if ptr == nil {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: PlatformAppEngine, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public func FfiConverterTypePlatformAppEngine_lift(_ pointer: UnsafeMutableRawPointer) throws -> PlatformAppEngine {
    return try FfiConverterTypePlatformAppEngine.lift(pointer)
}

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public func FfiConverterTypePlatformAppEngine_lower(_ value: PlatformAppEngine) -> UnsafeMutableRawPointer {
    return FfiConverterTypePlatformAppEngine.lower(value)
}

/**
 * Main Vauchi interface for mobile platforms.
 *
 * Uses on-demand storage connections for thread safety.
 */
public protocol VauchiPlatformProtocol: AnyObject {
    /**
     * Cancel a scheduled shred during the grace period.
     */
    func cancelShred(token: MobileShredToken) throws

    /**
     * Create a device-link session for the existing device
     * (initiator side).
     *
     * This is the orchestrator entry point — frontends register a
     * `DeviceLinkSessionListener`, call `start()` on the returned
     * session, and forward user actions via `confirm_manual` /
     * `confirm_ultrasonic` / `deny`. The session owns the relay-poll
     * loop, the QR-expiry deadline, and the user-confirm gate.
     * Replaces the legacy split between `start_device_link()`,
     * `listen_for_device_link_request()`, and
     * `send_device_link_response()`.
     *
     * Persistence: the session saves the updated `DeviceRegistry`
     * after `confirm_link` succeeds, closing a pre-existing gap
     * where the legacy single-shot path discarded it.
     */
    func createDeviceLinkSessionInitiator() throws -> MobileDeviceLinkSession

    /**
     * Create a new identity.
     */
    func createIdentity(displayName: String) throws

    /**
     * Create a multi-stage exchange session with the local identity and card.
     *
     * Serializes the identity public key and contact card into an exchange
     * payload that the multi-stage protocol will transfer to the peer.
     */
    func createMultistageSession() throws -> MobileMultiStageSession

    /**
     * Create an NFC exchange session as the initiator (reader side).
     *
     * Used by iOS (CoreNFC reader) and Android (NfcAdapter reader).
     */
    func createNfcInitiator() throws -> MobileNfcHandshake

    /**
     * Create an NFC exchange session as the responder (HCE side).
     *
     * Used by Android only (HostApduService card emulation).
     */
    func createNfcResponder() throws -> MobileNfcHandshake

    /**
     * Create a QR exchange session with proximity verification.
     *
     * Both parties display and scan QR codes. Uses fresh ephemeral keys
     * for full forward secrecy.
     */
    func createQrExchange(proximity: MobileProximityHandler) throws -> MobileExchangeSession

    /**
     * Create a QR exchange session with manual confirmation (no audio hardware).
     */
    func createQrExchangeManual() throws -> MobileExchangeSession

    /**
     * Get the device count.
     *
     * Returns the number of devices linked to this identity.
     */
    func deviceCount() throws -> UInt32

    /**
     * Encode data into multipart QR chunk strings for animated display.
     *
     * Each chunk fits within a QR code's data capacity. The chunks should
     * be displayed in sequence as an animated QR code for the scanning
     * device to reassemble using `MobileMultipartDecoder`.
     */
    func encodeMultipartQr(data: Data) -> [String]

    /**
     * Export the current storage key bytes for migration to secure storage.
     */
    func exportStorageKey() -> Data

    /**
     * Finalize a completed exchange session.
     *
     * Extracts the contact from the session's Complete state, saves it to storage,
     * and initializes the double ratchet. No relay notification is sent — face-to-face
     * exchange completes locally on both devices.
     *
     * On repeat exchange with the same peer, the contact card is upserted and the
     * ratchet state is re-initialized with fresh keys. Any relay messages in flight
     * from the previous ratchet epoch become permanently undecryptable. This is
     * intentional: a face-to-face re-exchange is a deliberate key ceremony that
     * establishes fresh forward secrecy.
     *
     * Old mailbox tokens (derived from the previous shared key) self-heal
     * via the relay's 30-day blob TTL — no active deregistration needed.
     * `exchange_timestamp` is updated by the SQL upsert in `save_contact()`.
     *
     * The session must be in the Complete state (i.e., the state machine has been
     * driven through all steps).
     */
    func finalizeExchange(session: MobileExchangeSession) throws -> MobileExchangeResult

    /**
     * Generate a device link QR code.
     *
     * Display this QR code on the existing device for a new device to scan.
     * The QR expires after 5 minutes (per ADR-035).
     */
    func generateDeviceLinkQr() throws -> MobileDeviceLinkData

    /**
     * Get list of linked devices.
     *
     * Returns information about all devices linked to this identity.
     * The first device (index 0) is the primary device.
     */
    func getDevices() throws -> [MobileDeviceInfo]

    /**
     * Get display name.
     */
    func getDisplayName() throws -> String

    /**
     * Get formatted fingerprint of own identity public key.
     *
     * Returns the fingerprint as 16 groups of 4 uppercase hex characters,
     * suitable for display and manual comparison with contacts.
     */
    func getOwnFingerprint() throws -> String

    /**
     * Get public ID.
     */
    func getPublicId() throws -> String

    /**
     * Get sync status.
     */
    func getSyncStatus() -> MobileSyncStatus

    /**
     * Execute irreversible crypto-shredding (Hard Shred).
     *
     * Requires the grace period to have elapsed. Destroys all key material,
     * secure-deletes the database, and removes all local data.
     *
     * **WARNING**: This operation is irreversible. All identity data will be
     * permanently destroyed.
     */
    func hardShred(token: MobileShredToken) throws -> MobileShredReport

    /**
     * Check if identity exists.
     */
    func hasIdentity() -> Bool

    /**
     * Import contacts from vCard data (supports 2.1 / 3.0 / 4.0).
     *
     * Pass the raw bytes of a `.vcf` file. Each parsed vCard becomes an
     * imported contact. Duplicates (by UID) are skipped. Returns counts
     * and per-contact warnings.
     */
    func importContactsFromVcf(data: Data) throws -> MobileImportResult

    /**
     * Check if certificate pinning is enabled.
     */
    func isCertificatePinningEnabled() -> Bool

    /**
     * Check if this device is the primary device (index 0).
     */
    func isPrimaryDevice() throws -> Bool

    /**
     * Listen for incoming device link request via relay (existing device / initiator).
     *
     * Creates an exchange offer with our identity, then polls until the new
     * device claims it. Returns the encrypted request and a token for the response.
     */
    func listenForDeviceLinkRequest(timeoutSecs: UInt64) throws -> MobileDeviceLinkRequest

    /**
     * Execute immediate crypto-shredding without grace period (Panic Shred).
     *
     * Loads pre-signed messages before destroying keys, then sends them
     * best-effort. Use only in emergencies.
     *
     * **WARNING**: This operation is irreversible and immediate. No grace period.
     */
    func panicShred() throws -> MobileShredReport

    /**
     * Parse a device link QR code.
     *
     * Call this on the new device after scanning the QR code displayed
     * on an existing device. Returns information about the identity
     * to link with.
     */
    func parseDeviceLinkQr(qrData: String) throws -> MobileDeviceLinkInfo

    /**
     * Send device link request via relay and wait for response (new device / responder).
     *
     * Uses two HTTP exchange cycles: creates a return channel, claims the
     * existing device's offer with our request, then polls for the response.
     */
    func sendDeviceLinkRequest(targetIdentity: String, senderToken: String, encryptedRequest: Data, timeoutSecs: UInt64) throws -> Data

    /**
     * Send device link response back via relay (existing device / initiator).
     *
     * Claims the return channel created by the new device, depositing the
     * encrypted response payload.
     */
    func sendDeviceLinkResponse(senderToken: String, encryptedResponse: Data) throws

    /**
     * Set the pinned certificate for relay TLS connections.
     *
     * The certificate should be in PEM format. Once set, only connections
     * to relay servers presenting this exact certificate will be allowed.
     */
    func setPinnedCertificate(certPem: String)

    /**
     * Set the platform keychain for crypto-shredding operations.
     *
     * Must be called before any shred operation. The keychain provides
     * access to the platform's native secure storage (iOS Keychain,
     * Android KeyStore) for SMK management.
     */
    func setPlatformKeychain(keychain: MobilePlatformKeychain)

    /**
     * Schedule crypto-shredding with 7-day grace period (Soft Shred).
     *
     * Returns a token that must be passed to `hard_shred()` after the grace period.
     * Also refreshes the pre-signed messages file for future panic shred.
     *
     * Requires `set_platform_keychain()` to be called first.
     */
    func softShred() throws -> MobileShredToken

    /**
     * Sync with relay server via OHTTP-encrypted HTTP.
     *
     * Creates a temporary `Vauchi` instance, connects, syncs, and maps the
     * outcome to `MobileSyncResult`. All synchronous — no tokio runtime needed.
     */
    func sync() throws -> MobileSyncResult

    /**
     * Async version of sync for mobile UI threads.
     *
     * Delegates to the synchronous `sync()` via `spawn_blocking` so
     * the core OHTTP HTTP calls don't block the async runtime.
     */
    func syncAsync() async throws -> MobileSyncResult

    /**
     * Unlink a device from this identity.
     *
     * This marks the device as revoked. It will no longer receive updates
     * and its keys will be rotated out. Returns true if the device was
     * found and unlinked.
     *
     * Note: Cannot unlink the current device (use identity deletion instead).
     * The device_index is the position in the devices list (0-based).
     */
    func unlinkDevice(deviceIndex: UInt32) throws -> Bool

    /**
     * Verify that shredding was successful by checking for residual data.
     *
     * Returns verification results showing which items were confirmed destroyed.
     */
    func verifyShred() throws -> MobileShredVerification
}

/**
 * Main Vauchi interface for mobile platforms.
 *
 * Uses on-demand storage connections for thread safety.
 */
open class VauchiPlatform:
