/*
 * Mobile-friendly protocol state enum (UniFFI-compatible).
 */

public enum MobileProtocolState {
    case idle
    case advertising
    case discovered
    case transferring(chunksSent: UInt16, chunksTotal: UInt16, chunksReceived: UInt16, peerChunksTotal: UInt16)
    case verifying
    case confirming
    case complete
    case finalized
    case failed(reason: String)
}

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public struct FfiConverterTypeMobileProtocolState: FfiConverterRustBuffer {
    typealias SwiftType = MobileProtocolState

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MobileProtocolState {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        case 1: return .idle

        case 2: return .advertising

        case 3: return .discovered

        case 4: return try .transferring(chunksSent: FfiConverterUInt16.read(from: &buf), chunksTotal: FfiConverterUInt16.read(from: &buf), chunksReceived: FfiConverterUInt16.read(from: &buf), peerChunksTotal: FfiConverterUInt16.read(from: &buf))

        case 5: return .verifying

        case 6: return .confirming

        case 7: return .complete

        case 8: return .finalized

        case 9: return try .failed(reason: FfiConverterString.read(from: &buf))

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MobileProtocolState, into buf: inout [UInt8]) {
        switch value {
        case .idle:
            writeInt(&buf, Int32(1))

        case .advertising:
            writeInt(&buf, Int32(2))

        case .discovered:
            writeInt(&buf, Int32(3))

        case let .transferring(chunksSent, chunksTotal, chunksReceived, peerChunksTotal):
            writeInt(&buf, Int32(4))
            FfiConverterUInt16.write(chunksSent, into: &buf)
            FfiConverterUInt16.write(chunksTotal, into: &buf)
            FfiConverterUInt16.write(chunksReceived, into: &buf)
            FfiConverterUInt16.write(peerChunksTotal, into: &buf)

        case .verifying:
            writeInt(&buf, Int32(5))

        case .confirming:
            writeInt(&buf, Int32(6))

        case .complete:
            writeInt(&buf, Int32(7))

        case .finalized:
            writeInt(&buf, Int32(8))

        case let .failed(reason):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(reason, into: &buf)
        }
    }
}

